#include <nlohmann/json.hpp>
#include <filesystem>
#include <fstream>
#include <iostream>
using J=nlohmann::json;namespace fs=std::filesystem;
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("usage cases_directory result");const fs::path root=argv[1],output=argv[2];if(fs::exists(output))throw std::runtime_error("fresh report");J checks=J::array();int failed=0;auto check=[&](std::string name,bool pass){checks.push_back({{"id",name},{"pass",pass}});failed+=!pass;};auto load=[&](const std::string&name){std::ifstream f(root/(name+"-audit-v2.json"));return J::parse(f);};
 for(const auto&name:{"control-valid","control-cancellation-up","control-unknown-down-released","control-compacted-prefix","control-provenance-join","control-measurement-actions"}){auto r=load(name);check(name,r.at("integrity").get<bool>()&&r.at("complete_prefix_evidence").get<bool>()&&r.at("metrics_verified").get<bool>()&&r.at("plan_join_complete").get<bool>()&&r.at("coordinate_join_complete").get<bool>()&&r.at("input_bindings").size()==3&&r.at("verifier_binary").at("sha256").get<std::string>().size()==64);}
 for(const auto&name:{"receipt-plan-mismatch","cross-intent-up","completed-intent-rebirth","unknown-release-overwritten","fabricated-cost-distribution","500ms-raw-latency-green-summary","attempts-field-mismatch","pixel-incomplete","compacted-prefix-step-mismatch","same-note-new-intent-rebirth","provenance-report-event-mismatch","provenance-duplicate-event","provenance-event-missing"}){const auto r=load(name);check(name,!r.at("integrity").get<bool>()&&!r.at("complete_prefix_evidence").get<bool>()&&!r.at("errors").empty());}
 {const auto r=load("legacy-no-coordinate-join");check("legacy_coordinate_gap_explicit",r.at("integrity").get<bool>()&&!r.at("coordinate_join_complete").get<bool>()&&!r.at("complete_prefix_evidence").get<bool>());}
 {const auto r=load("control-valid");check("warmup_only_actions_not_measurement_actions",r.at("measurement_phase_counts")==J::array({0,0,0})&&r.at("measurement_all_phase_lateness_ms").at("n")==0&&r.at("measurement_window_start_ns")==256100);}
 {const auto r=load("control-measurement-actions");check("measurement_phases_and_lateness_recomputed",r.at("measurement_phase_counts")==J::array({1,0,1})&&r.at("measurement_all_phase_lateness_ms").at("n")==2&&r.at("measurement_all_phase_lateness_ms").at("p99")==.00001);}
 const std::map<std::string,std::string>reasons={{"receipt-plan-mismatch","receipt_plan_step_source_cursor_join"},{"cross-intent-up","move_up_without_same_intent_down"},{"completed-intent-rebirth","terminal_intent_replayed"},{"unknown-release-overwritten","release_verified_overrides_uncertainty"},{"fabricated-cost-distribution","distribution:capture_to_owner_ms"},{"500ms-raw-latency-green-summary","distribution:capture_to_owner_ms"},{"attempts-field-mismatch","attempt_length_and_reported_count"},{"pixel-incomplete","pixel_input_incomplete"},{"compacted-prefix-step-mismatch","receipt_plan_step_source_cursor_join"},{"same-note-new-intent-rebirth","note_identity_rebirth"},{"provenance-report-event-mismatch","run_provenance_join"},{"provenance-duplicate-event","run_provenance_join"},{"provenance-event-missing","run_provenance_join"}};
 for(const auto&[name,reason]:reasons){const auto r=load(name);const auto&errors=r.at("errors");check("specific_rejection:"+name,std::find(errors.begin(),errors.end(),reason)!=errors.end());}
 J result={{"schema","pas.audit-v2.independent-controls.v1"},{"assertions",checks.size()},{"failed",failed},{"checks",checks},{"qualification","offline Linux software checks only; no Windows/QPC/device qualification"}};std::ofstream out(output);out<<result.dump(2)<<'\n';std::cout<<result.dump(2)<<'\n';return failed?1:0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
